mapper.select:
select  from task_lineage_evidence
where tenant_id=#{query.tenantId}
and root_task_id=#{query.rootTaskId}
and task_id=#{query.taskId}
and executor_agent_id=#{query.agentId}
and correlation_id=#{query.correlationId}
and (origin_principal_type=#{query.principalType} or actor_principal_type=#{query.principalType})
and (origin_principal_id=#{query.principalId} or actor_principal_id=#{query.principalId})
and credential_id=#{query.credentialId}
and department_id=#{query.departmentId}
and group_id=#{query.groupId}
and failure_domain=#{query.failureDomain}
order by occurred_at desc,evidence_id desc limit #{query.limit}
